import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv.lstrip("\ufeff"), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if record and any(field.strip() for field in record):
            records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    def header_score(record: list[str]) -> int:
        score = 0
        for field in record:
            name = field.strip().lower()
            if re.search(r"(^|[^a-z])gene([^a-z]|$)", name):
                score += 1
            if re.search(r"dataset|study|experiment", name):
                score += 1
            if re.search(r"log\s*2|log2|fold.?change|\bfc\b", name):
                score += 1
        return score

    header_index = next(
        (i for i, record in enumerate(records) if header_score(record) >= 2),
        0,
    )
    columns = [field.strip() for field in records[header_index]]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    width = len(columns)
    rows = []
    for record in records[header_index + 1:]:
        fields = list(record)
        if len(fields) > width and width:
            fields = fields[:width - 1] + [",".join(fields[width - 1:])]
        elif len(fields) < width:
            fields.extend([""] * (width - len(fields)))
        rows.append(fields)

    return {"columns": columns, "rows": rows}
